package ai.taskforge.domain;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="tasks",indexes={@Index(name="idx_task_assignee_status",columnList="assignee_id,status"),@Index(name="idx_task_due",columnList="dueDate")}) public class Task {
 @Id @GeneratedValue private UUID id; @Column(nullable=false) private String title; @Column(length=4000) private String description; @Enumerated(EnumType.STRING) @Column(nullable=false) private TaskStatus status=TaskStatus.TODO; @Enumerated(EnumType.STRING) @Column(nullable=false) private Priority priority=Priority.MEDIUM; private int priorityScore; private LocalDate dueDate; private String category; private String estimatedEffort; private boolean aiGenerated; private double aiConfidence; @ManyToOne @JoinColumn(name="assignee_id") private AppUser assignee; @ManyToOne @JoinColumn(name="created_by_id",nullable=false) private AppUser createdBy; @ManyToOne @JoinColumn(name="project_id") private Project project; @Column(nullable=false,updatable=false) private Instant createdAt=Instant.now(); private Instant updatedAt=Instant.now();
 @ManyToMany @JoinTable(name="task_dependencies",joinColumns=@JoinColumn(name="task_id"),inverseJoinColumns=@JoinColumn(name="depends_on_id")) private Set<Task> dependencies=new HashSet<>(); protected Task(){} public Task(String t,String d,AppUser c){title=t;description=d;createdBy=c;} @PreUpdate void touch(){updatedAt=Instant.now();} public UUID getId(){return id;} public String getTitle(){return title;} public String getDescription(){return description;} public TaskStatus getStatus(){return status;} public Priority getPriority(){return priority;} public int getPriorityScore(){return priorityScore;} public LocalDate getDueDate(){return dueDate;} public String getCategory(){return category;} public String getEstimatedEffort(){return estimatedEffort;} public boolean isAiGenerated(){return aiGenerated;} public double getAiConfidence(){return aiConfidence;} public AppUser getAssignee(){return assignee;} public Project getProject(){return project;} public Set<Task> getDependencies(){return dependencies;} public void update(String title,String description,TaskStatus status,Priority priority,LocalDate due,AppUser assignee,Project project,String category,int score){this.title=title;this.description=description;this.status=status;this.priority=priority;this.dueDate=due;this.assignee=assignee;this.project=project;this.category=category;this.priorityScore=score;} public void addDependency(Task task){dependencies.add(task);} }
